compliant:
import { Array, pipe } from "effect"

export interface StockItem {
  readonly sku: string
  readonly warehouse: string
  readonly available: number
  readonly reorderPoint: number
}

export interface ReorderEntry {
  readonly sku: string
  readonly warehouse: string
  readonly quantity: number
}

export const buildReorderReport = (
  items: ReadonlyArray<StockItem>,
  warehouse: string
): ReadonlyArray<ReorderEntry> => {
  const candidates = pipe(
    items,
    Array.filter(
      (item: StockItem) =>
        item.warehouse === warehouse && item.available < item.reorderPoint
    )
  )

  return pipe(
    candidates,
    Array.map((item) => ({
      sku: item.sku,
      warehouse: item.warehouse,
      quantity: item.reorderPoint - item.available
    }))
  )
}
